import{_ as o,a0 as l,w as r,s as i,ao as d,I as p,x as a,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"命令行星期二——第八部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令行星期二——第八部分 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行星期二——第八部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行星期二——第八部分 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20180813 Command Line Tuesdays--Part Eight","title":"命令行星期二——第八部分","tag":"201408","desc":""},"relativePath":"201408/20180813 Command Line Tuesdays--Part Eight.md","filePath":"[post].md"}'),h={name:"201408/20180813 Command Line Tuesdays--Part Eight.md"};function m(u,e,T,f,b,C){const t=l("Link");return r(),i("div",null,[e[13]||(e[13]=d(`<h1 id="命令行星期二——第八部分" tabindex="-1">命令行星期二——第八部分 <a class="header-anchor" href="#命令行星期二——第八部分" aria-label="Permalink to “命令行星期二——第八部分”">​</a></h1><p>唷，唷，极客们！我们回来了，来完成最后一章的CLT。今天，我们将讨论一下任务控制。在这个里头，我们也将学习怎样来控制运行在我们计算机上的进程！</p><h3 id="一个例子" tabindex="-1">一个例子 <a class="header-anchor" href="#一个例子" aria-label="Permalink to “一个例子”">​</a></h3><p>正如我们所学的，我们可以直接在CLI中输入程序名称来运行该程序。例如，dolphin。如果我们输入：</p><pre><code>dolphin
</code></pre><p>……dolphin，这个文件管理器，就打开了。如果在这个进程打开时你查看终端，你会发现不能访问命令提示符了，而且你也不能在同一个窗口中写一个新命令进去了。如果你终止dolphin，提示符又会出现了，而你又能输入一个新命令到shell中去了。那么，我们怎么能在CLI运行一个程序时，同时又能获得提示符以便进一步发命令。</p><pre><code>dolphin &amp;
</code></pre><p>……现在你让dolphin文件管理器在后台运行了，终端就可以空出来输入你需要的另外一个命令了。</p><p>现在，假设你忘了在dolphin后面输入‘&amp;’字符，你只需要输入‘ctrl+z’，它会停止你的进程并把它放到空闲列表中去。要继续停止的进程，输入：</p><pre><code>bg
</code></pre><p>……它会从后台重启进程。</p><h3 id="jobs-ps" tabindex="-1">jobs, ps <a class="header-anchor" href="#jobs-ps" aria-label="Permalink to “jobs, ps”">​</a></h3><p>由于我们在后台运行着进程，你可以使用jobs或者使用ps来列出它们。试试吧，只要输入jobs或者输入ps就行了。下面是我得到的结果：</p><pre><code>nenad@linux-zr04:~&gt; ps
PID TTY          TIME CMD
8356 pts/1    00:00:00 bash
8401 pts/1    00:00:00 dolphin
8406 pts/1    00:00:00 kbuildsycoca4
8456 pts/1    00:00:00 ps
</code></pre><h3 id="杀死进程" tabindex="-1">杀死进程 <a class="header-anchor" href="#杀死进程" aria-label="Permalink to “杀死进程”">​</a></h3><p>如果有个进程无响应了，怎么来处理掉它呢？可以使用kill命令。让我们在先前提到的dolphin进程上试试。首先，我们必须使用ps来鉴别该进程的PID。在我上述情况中，dolphin的PID是8401。那么让我们来杀死它，我只要输入：</p><pre><code>kill 8401
</code></pre><p>……那么，它就把dolphin给杀死了。</p><h3 id="kill的更多细节" tabindex="-1">kill的更多细节 <a class="header-anchor" href="#kill的更多细节" aria-label="Permalink to “kill的更多细节”">​</a></h3><p>kill的存在，不仅仅是为了终止进程，它最初是设计用来发送信号给进程。当然，有许多kill信号可以使用，根据你使用的应用程序不同而不同。请看下面的表：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/08/snapshot1.png" alt=""></p><p>务必试试这些信号。</p><h3 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to “结尾”">​</a></h3><p>我们以本节课来结束我们的CLT系列和周二必达，我希望其他像我这样的新手们能设法在他们的思想中摆脱控制台的神秘而学习掌握一些基本技能。现在对你们而言，所有剩下来要做的事，就是尽情摆弄它吧（只是别把“/”目录搞得太乱七八糟，因而你也不会诋毁什么东西了 😄）。</p><p>我们将在不久的将来看到其它更多的东西，因为有更多的系列文章来自这些文章的出处。别走开，同时……</p><h3 id="尽情享受" tabindex="-1">……尽情享受！ <a class="header-anchor" href="#尽情享受" aria-label="Permalink to “……尽情享受！”">​</a></h3><hr>`,27)),p("p",null,[e[1]||(e[1]=a("via: ",-1)),n(t,{href:"https://news.opensuse.org/2014/08/12/command-line-tuesdays-part-eight/"},{default:s(()=>[...e[0]||(e[0]=[a("https://news.opensuse.org/2014/08/12/command-line-tuesdays-part-eight/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=a("作者：",-1)),n(t,{href:"https://news.opensuse.org/author/holden87/"},{default:s(()=>[...e[2]||(e[2]=[a("Nenad Latinović",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),n(t,{href:"https://github.com/GOLinux"},{default:s(()=>[...e[3]||(e[3]=[a("GOLinux",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const k=o(h,[["render",m]]);export{L as __pageData,k as default};
